<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { t } from '../i18n'
import type { TextureRecord } from '../textureTypes'
const props=defineProps<{csrfToken:string}>(),emit=defineEmits<{expired:[]}>()
const enabled=ref(false),categories=ref(''),state=ref('pending'),items=ref<TextureRecord[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),reason=ref('')
async function load(){error.value='';try{const r=await fetch('/api/admin/review?'+new URLSearchParams({state:state.value,page:String(page.value)}));if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);items.value=d.textures;total.value=d.total}catch(e){error.value=(e as Error).message}}
async function write(path:string,body:unknown){busy.value=true;error.value='';try{const r=await fetch(path,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify(body)});if(r.status===401){emit('expired');return};if(!r.ok){const d=await r.json();throw new Error(d.error)};await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{const r=await fetch('/api/content-policy');if(!r.ok)throw new Error();const d=await r.json();enabled.value=d.reviewUploads;categories.value=d.categories.join('\n')}catch{error.value='暂时无法读取内容设置'};await load()})
</script>
<template><section class="settings-section panel"><details class="advanced-group"><summary>{{ t('分类与上传审核设置') }}</summary><form class="settings-form" @submit.prevent="write('/api/admin/content-policy',{reviewUploads:enabled,categories:categories.split('\n').map(s=>s.trim()).filter(Boolean)})"><fieldset :disabled="busy"><label class="checkbox-label"><input v-model="enabled" type="checkbox" />{{ t('新上传和资料修改需要审核') }}</label><label class="binding-field"><span>{{ t('分类，每行一个') }}</span><textarea v-model="categories" rows="4" /></label><button class="primary-button">{{ t('保存内容设置') }}</button></fieldset></form></details><div class="settings-actions"><h2>{{ t('材质审核') }}</h2><select v-model="state" :aria-label="t('审核状态')" @change="page=1;load()"><option value="pending">{{ t('待审核') }}</option><option value="approved">{{ t('已通过') }}</option><option value="rejected">{{ t('已拒绝') }}</option></select><button class="secondary-button" type="button" :disabled="busy" @click="load">{{ t('刷新列表') }}</button></div><label class="binding-field"><span>{{ t('审核备注（可选）') }}</span><input v-model="reason" maxlength="200" /></label><p v-if="!items.length">{{ t('没有对应的材质') }}</p><div class="review-list"><article v-for="item in items" :key="item.id" class="review-item"><img :src="'/api/admin/review/'+item.id+'/image'" :alt="item.name" width="80" height="80" /><div><strong>{{ item.name }}</strong><p>{{ item.description }}</p><small>{{ item.category }} / {{ item.tags?.join(', ') }}</small><p v-if="item.reviewReason">{{ item.reviewReason }}</p><div class="settings-actions"><button class="secondary-button" type="button" :disabled="busy||state==='approved'" @click="write('/api/admin/review/'+item.id,{state:'approved',reason})">{{ t('通过') }}</button><button class="danger-button" type="button" :disabled="busy||state==='rejected'" @click="write('/api/admin/review/'+item.id,{state:'rejected',reason})">{{ t('拒绝') }}</button></div></div></article></div><div class="settings-actions"><button class="secondary-button" type="button" :disabled="busy||page<=1" @click="page--;load()">{{ t('上一页') }}</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><button class="secondary-button" type="button" :disabled="busy||page*20>=total" @click="page++;load()">{{ t('下一页') }}</button></div><p v-if="error" class="form-error" role="alert">{{ t(error) }}</p></section></template>
